function words(ctx,text,x,y,maxWidth,size=28,line=38){ctx.font=`${size}px Georgia`;let out='',row=0;for(const word of text.split(' ')){if(ctx.measureText(out+word).width>maxWidth&&out){ctx.fillText(out.trim(),x,y+row*line);out='';row++;}out+=word+' ';}ctx.fillText(out.trim(),x,y+row*line);return y+(row+1)*line;}
function artTexture(item,number){const c=document.createElement('canvas');c.width=768;c.height=900;const p=c.getContext('2d');p.fillStyle='#e6d5ac';p.fillRect(0,0,768,900);p.strokeStyle='#9b7a42';p.lineWidth=4;p.strokeRect(28,28,712,844);p.strokeRect(38,38,692,824);p.fillStyle='#21443b';p.textAlign='center';p.font='18px sans-serif';p.fillText('THE NORMALCY COLLECTION',384,82);p.font=item.code?'86px Georgia':'100px Georgia';p.fillText(item.code||number,384,194);let y=words(p,item.title,384,260,635,43,50);p.font='20px sans-serif';p.fillStyle='#856534';p.fillText(String(item.year),384,y+20);if(item.code){p.fillStyle='#9b4937';p.font='19px sans-serif';p.fillText('ARCHIVE FILE',384,225);}
 if(item.kind==='map'){const nodes=item.room==='teapot'?[[200,450,'WYOMING'],[540,600,'CALIFORNIA']]:[[150,450,'U.S.'],[570,420,'GERMANY'],[470,630,'ALLIES']];p.strokeStyle='#567260';p.lineWidth=8;p.beginPath();nodes.forEach(([x,y],i)=>i?p.lineTo(x,y):p.moveTo(x,y));p.closePath();p.stroke();for(const[x,y,t]of nodes){p.fillStyle='#245447';p.beginPath();p.arc(x,y,23,0,7);p.fill();p.font='22px sans-serif';p.fillText(t,x,y+55);}p.font='17px sans-serif';p.fillText('SCHEMATIC · NOT TO SCALE',384,735);}
 else if(item.kind==='poster'){p.fillStyle='#325647';p.beginPath();p.moveTo(180,600);p.lineTo(384,420);p.lineTo(588,600);p.closePath();p.fill();for(let i=0;i<5;i++)p.fillRect(210+i*72,610,40,90);p.fillRect(180,716,408,20);p.font='27px Georgia';p.fillText('A RETURN TO NORMALCY?',384,398);}
 else{p.strokeStyle='#8f8060';p.lineWidth=2;for(let i=0;i<9;i++){const yy=Math.max(410,y+60)+i*26;p.beginPath();p.moveTo(140,yy);p.lineTo(i===8?440:628,yy);p.stroke();}p.strokeStyle='#9b4937';p.lineWidth=3;p.strokeRect(270,705,228,60);p.fillStyle='#9b4937';p.font='19px sans-serif';p.fillText('EVIDENCE FILE',384,743);}
 p.fillStyle='#385344';p.font='16px sans-serif';p.fillText('THE NORMALCY MUSEUM',384,816);p.fillText('Inspect for history, evidence & source links',384,844);const t=new THREE.CanvasTexture(c);t.colorSpace=THREE.SRGBColorSpace;return t;}
function label(g,title,sub,w=1.65,y=.95,z=.61){const c=document.createElement('canvas');c.width=1024;c.height=220;const p=c.getContext('2d');p.fillStyle='#173d33';p.fillRect(0,0,1024,220);p.strokeStyle='#bb9a58';p.lineWidth=5;p.strokeRect(8,8,1008,204);p.fillStyle='#ead9b4';p.textAlign='center';words(p,title,512,75,950,39,46);p.fillStyle='#c4b48b';p.font='23px sans-serif';p.fillText(sub,512,185);const t=new THREE.CanvasTexture(c);t.colorSpace=THREE.SRGBColorSpace;const o=new THREE.Mesh(new THREE.PlaneGeometry(w,w*.215),new THREE.MeshBasicMaterial({map:t}));o.position.set(0,y,z);g.add(o);return o;}
function table(g,w=1.85,d=1.1){cube(g,w,.12,d,0,1.02,0,wood);cube(g,w+.06,.035,d+.06,0,1.095,0,gold);for(const x of [-w/2+.15,w/2-.15])for(const z of [-d/2+.15,d/2-.15]){cube(g,.1,.91,.1,x,.475,z,wood);cube(g,.12,.13,.12,x,.08,z,gold);}cube(g,w-.1,.22,.06,0,.86,d/2-.06,wood);}
function flatDocument(g,item,number){const mesh=new THREE.Mesh(new THREE.PlaneGeometry(.67,.8),new THREE.MeshBasicMaterial({map:artTexture(item,number),side:THREE.DoubleSide}));mesh.rotation.x=-Math.PI/2;mesh.position.set(0,1.116,0);g.add(mesh);return mesh;}
function gramophone(g){cube(g,.8,.2,.7,0,1.2,0,wood);cube(g,.85,.05,.75,0,1.31,0,gold);const disk=new THREE.Mesh(diskGeometry,edge);disk.position.set(-.05,1.35,0);disk.scale.setScalar(.75);g.add(disk);cyl(g,.06,.06,.022,-.05,1.37,0,gold);line(g,[[.3,1.35,-.2],[.4,1.55,-.3],[.15,1.55,.05],[0,1.4,.2]]);line(g,[[.32,1.32,-.22],[.32,1.8,-.22],[.1,2,-.2]],gold,.055);const profile=[[.045,0],[.07,.12],[.13,.24],[.26,.37],[.46,.49]].map(([x,y])=>new THREE.Vector2(x,y));const horn=new THREE.Mesh(new THREE.LatheGeometry(profile,40),new THREE.MeshStandardMaterial({color:0xc5a25a,metalness:.7,roughness:.34,side:THREE.DoubleSide}));horn.rotation.x=Math.PI/2.8;horn.position.set(.1,1.98,-.2);g.add(horn);}
function radio(g){cube(g,1.18,.72,.45,0,1.49,0,wood);cube(g,1.05,.6,.025,0,1.49,.24,gold);cube(g,.97,.53,.028,0,1.49,.26,edge);for(let i=0;i<14;i++)cube(g,.02,.34,.025,-.42+i*.065,1.57,.29,gold);for(const x of [-.33,.33]){const k=cyl(g,.065,.065,.06,x,1.3,.31,gold,24);k.rotation.x=Math.PI/2;}cube(g,.29,.09,.03,0,1.3,.31,paper);}
function oil(g){cyl(g,.34,.34,.89,0,1.56,0,iron);for(const y of [1.14,1.35,1.78,1.99])cyl(g,.355,.355,.035,0,y,0,gold);cyl(g,.065,.065,.03,.17,2.02,.08,edge);label(g,'NAVAL RESERVES','PUBLIC RESOURCE',.58,1.58,.356);}
function suitcase(g){cube(g,1.12,.52,.7,0,1.37,0,leather);for(const x of [-.37,.37]){cube(g,.07,.54,.72,x,1.37,0,edge);cube(g,.11,.13,.03,x,1.38,.37,gold);}line(g,[[-.18,1.63,0],[-.18,1.78,0],[.18,1.78,0],[.18,1.63,0]],edge,.035);for(const x of [-.54,.54])for(const z of [-.34,.34])cube(g,.09,.1,.09,x,1.6,z,gold);}
function ship(g){const hull=new THREE.Shape();hull.moveTo(-.8,0);hull.lineTo(-.62,-.2);hull.lineTo(.62,-.2);hull.lineTo(.85,0);hull.closePath();const o=new THREE.Mesh(new THREE.ExtrudeGeometry(hull,{depth:.32,bevelEnabled:true,bevelSize:.035,bevelThickness:.035,bevelSegments:1,steps:1}),iron);o.position.set(0,1.46,-.16);g.add(o);cube(g,1.25,.09,.33,0,1.48,0,wood);cube(g,.4,.18,.27,-.07,1.59,0,paper);for(const x of [-.14,.12])cyl(g,.06,.06,.18,x,1.77,0,iron);line(g,[[.4,1.52,0],[.4,2.02,0]],gold,.015);line(g,[[-.65,1.49,0],[.4,1.99,0],[.7,1.49,0]],edge,.005);for(const x of [-.5,.5])cube(g,.1,.16,.24,x,1.18,0,gold);cube(g,1.6,.06,.53,0,1.11,0,edge);}
function ledger(g,item,n){for(const x of [-.33,.33]){const book=cube(g,.63,.09,.78,x,1.15,0,paper);book.rotation.z=x<0?-.08:.08;}cube(g,.04,.12,.8,0,1.14,0,leather);flatDocument(g,item,n).position.y=1.207;}
function files(g,item,n){for(let i=0;i<4;i++){const a=cube(g,.75,.035,.85,(i%2)*.045,1.13+i*.04,0,i%2?paper:leather);a.rotation.y=(i-2)*.035;}flatDocument(g,item,n).position.y=1.28;}
function crate(g){cube(g,1,.64,.76,0,1.43,0,wood);for(const x of [-.43,.43])cube(g,.1,.68,.8,x,1.43,0,gold);for(let i=0;i<4;i++)cube(g,.84,.018,.015,0,1.2+i*.15,.389,edge);label(g,'IMPORTS','TARIFF · 1922',.69,1.47,.4);}
function scroll(g,item,n){flatDocument(g,item,n);for(const z of [-.43,.43]){const c=cyl(g,.055,.055,.83,0,1.17,z,paper);c.rotation.z=Math.PI/2;for(const x of [-.45,.45]){const a=cyl(g,.065,.065,.08,x,1.17,z,gold);a.rotation.z=Math.PI/2;}}}
const makers={phonograph:gramophone,radio,oil,suitcase,ship,ledger,files,crate,scroll};
export function buildCollection(scene,rooms,colliders){const targets=[],instances=[];
 const bind=(root,data)=>{root.traverse(o=>{if(o.isMesh){o.userData.collection=data;targets.push(o);}});root.userData.collection=data;instances.push(root);};
 for(const room of rooms.filter(r=>r.id!=='reference')){const items=EXHIBITS.filter(e=>e.room===room.id);items.forEach((item,i)=>{const six=items.length===6,north=i<(six?3:2),z=room.z+(north?-3.35:3.35),x=room.side*10.15+(six?[-3.3,0,3.3,3.3,0,-3.3][i]:[-2.65,2.65,2.65,-2.65][i]),number=String(i+1).padStart(2,'0');const g=new THREE.Group();g.position.set(x,0,z);g.rotation.y=north?0:Math.PI;scene.add(g);
  if(['document','poster','map'].includes(item.kind)){g.position.z=room.z+(north?-4.72:4.72);cube(g,2.1,2.35,.12,0,2.48,0,wood);cube(g,1.99,2.24,.025,0,2.48,.075,gold);const panel=new THREE.Mesh(new THREE.PlaneGeometry(1.86,2.18),new THREE.MeshBasicMaterial({map:artTexture(item,number)}));panel.position.set(0,2.48,.093);g.add(panel);label(g,item.title,(item.code||number)+' / CLICK TO INSPECT',2.1,1.08,.1);}
  else{table(g);(makers[item.kind]||files)(g,item,number);label(g,item.title,number+' / CLICK TO INSPECT');colliders.push({minX:x-.96,maxX:x+.96,minZ:z-.6,maxZ:z+.6,exhibit:item.id});}
  bind(g,{type:'exhibit',id:item.id,room:room.id});
 });
 const desk=new THREE.Group();desk.position.set(room.side*14.1,0,room.z);desk.rotation.y=room.side<0?Math.PI/2:-Math.PI/2;scene.add(desk);table(desk,1.6,.85);cube(desk,1.15,.09,.62,0,1.22,0,ink).rotation.x=.17;label(desk,room.id==='study'?'THE FINAL SCROLL':'EVIDENCE DESK','CONNECT THE CLUES',1.43,1.38,.39);cyl(desk,.1,.12,.12,.5,1.24,0,gold);bind(desk,{type:'puzzle',room:room.id});colliders.push({minX:room.side*14.1-.5,maxX:room.side*14.1+.5,minZ:room.z-.85,maxZ:room.z+.85,puzzle:room.id});
 }
 const r=rooms.find(r=>r.id==='reference');for(const dx of [-3.1,3.1]){const topic=dx<0?'a1':'d1',g=new THREE.Group();g.position.set(r.side*10.15+dx,0,r.z-4.4);scene.add(g);cube(g,2.5,3,.18,0,1.5,-.2,wood);for(const x of [-1.2,1.2])cube(g,.12,3,.6,x,1.5,0,wood);for(const y of [.1,1,1.9,2.9])cube(g,2.5,.1,.65,0,y,0,wood);for(let row=0;row<3;row++)for(let i=0;i<10;i++){const m=material([0x355246,0x613f32,0x8f7644][(i+row)%3]);cube(g,.16,.55+(i%3)*.08,.34,-1+i*.22,.43+row*.91,.02,m);cube(g,.12,.022,.015,-1+i*.22,.42+row*.91,.199,gold);}label(g,topic==='a1'?'LIBRARY A1':'LIBRARY D1','CLICK FOR ESSENTIAL QUESTION',2.45,3.37,.39);bind(g,{type:'reference',room:'reference',topic});}
 const ref=new THREE.Group();ref.position.set(10.15,0,r.z+1.4);ref.rotation.y=Math.PI;scene.add(ref);table(ref,2.5,1.1);label(ref,'THE REFERENCE COLLECTION','SOURCES · OBJECTIVES · CREDITS',2.35,1.35,.4);bind(ref,{type:'reference',room:'reference'});colliders.push({minX:8.85,maxX:11.45,minZ:r.z+.8,maxZ:r.z+2});
 return {targets,instances};
}
